#!/usr/bin/env python3
"""Batch evidence pull for the global macro map question. Read-only ia_cli calls."""
import json, subprocess, sys

ENGINE = "/private/tmp/r68/accept/install/ia_cli.py"

def call(args):
    p = subprocess.run([sys.executable, ENGINE] + args, capture_output=True, text=True, cwd="/private/tmp/r68/accept/install")
    raw = p.stdout
    start = raw.find("{")
    if start < 0:
        return {"_err": p.stderr[-300:], "_stdout": raw[:300]}
    try:
        return json.loads(raw[start:])
    except Exception as e:
        return {"_err": "parse:" + str(e), "_stdout": raw[:300]}

out = {}

# --- 1. policy rate histories ---
for metric, start, end in [
    ("DFF", "2025-10-01", "2026-11-19"),
    ("JP_POLICY_RATE", "2017-01-01", "2026-11-19"),
    ("ECB_DFR", "2022-01-01", "2026-11-19"),
    ("ECB_MRO", "2022-01-01", "2026-11-19"),
]:
    r = call(["history", "--metric", metric, "--start", start, "--end", end])
    d = r.get("data", {})
    series = d.get("series", d.get("observations", []))
    rows = []
    if isinstance(series, dict):
        for k in sorted(series):
            rows.append({"date": k, "value": series[k]})
    elif isinstance(series, list):
        for o in series:
            rows.append({"date": o.get("date", o.get("observation_date")), "value": o.get("value")})
    out["hist_" + metric] = {
        "n": len(rows),
        "unit": d.get("unit"),
        "note": (d.get("note") or "")[:200],
        "first": rows[0] if rows else None,
        "last": rows[-1] if rows else None,
        "all": rows if metric != "DFF" else None,
    }
    if metric == "DFF":
        # monthly path: last obs per month + month-to-month change
        bym = {}
        for rw in rows:
            bym[rw["date"][:7]] = rw["value"]  # last wins (sorted)
        out["dff_monthly_path"] = {m: bym[m] for m in sorted(bym)}

# --- 2. 12m self-pair interval changes (P2-2 formal path) ---
for m in ["SPX", "NIKKEI225", "USDJPY", "DXY", "GOLD_F", "UST_10Y", "SHCOMP", "DAX", "HY_OAS", "USDCNY", "VIX", "HSI"]:
    r = call(["compare", "--metrics", m + "," + m, "--start", "2025-11-19", "--end", "2026-11-19"])
    d = r.get("data", {})
    sides = d.get("sides", [])
    rec = {"ok": r.get("ok")}
    if sides:
        ic = sides[0].get("interval_change_common_window") or {}
        rec.update({
            "change": ic.get("value"),
            "unit": ic.get("change_unit"),
            "basis": ic.get("basis_date"),
            "end": ic.get("end_date"),
        })
    else:
        rec["err"] = json.dumps(d, ensure_ascii=False)[:220]
    out["chg12m_" + m] = rec

# --- 3. transmission correlations (descriptive) ---
for a, b, lbl in [
    ("TIPS_10Y", "USDJPY", "tips_usdjpy"),
    ("TIPS_10Y", "GOLD_F", "tips_gold"),
    ("UST_10Y", "USDJPY", "ust_usdjpy"),
    ("VIX", "GOLD_F", "vix_gold"),
    ("BEI_10Y", "GOLD_F", "bei_gold"),
    ("TIPS_10Y", "NIKKEI225", "tips_nikkei"),
    ("UST_10Y", "SPX", "ust_spx"),
]:
    r = call(["compare", "--metrics", a + "," + b, "--start", "2025-11-19", "--end", "2026-11-19"])
    d = r.get("data", {})
    cor = d.get("correlation") or {}
    al = d.get("alignment") or {}
    out["corr_" + lbl] = {
        "pearson": cor.get("pearson"),
        "n": al.get("n_common"),
        "mode": al.get("mode"),
        "change_basis": d.get("change_basis"),
        "gate": al.get("research_mode_gate"),
        "warn": (d.get("warnings") or [])[:2],
    }

print(json.dumps(out, ensure_ascii=False, indent=1, default=str))

